contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint balBefore = address(this).balance;
        uint cBalBefore = address(c).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint cBalAfterDeposit = address(c).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = address(this).balance;
        uint cBalAfter = address(c).balance;

        assert(
            !reverted &&
            cBalAfterDeposit == cBalBefore + amount &&
            cBalAfter == cBalBefore &&
            balAfter == balBefore
        );
    }

    receive() external payable {}
}

